import { component, $state, $derived } from './framework';
import type { Renderable } from './framework';

type ListProps<T> = { items: readonly T[]; children: (item: T) => Renderable };
export const List = component(<T,>({ items, children }: ListProps<T>) => <div>{items.map(children)}</div>);
const view = <List items={[{ id: 1, name: 'Alice' }]}>{item => <span>{item.name}</span>}</List>;
const explicit = <List<number> items={[1]}>{item => item.toFixed()}</List>;

